def weave_count(a, b, tape):
    if len(a) + len(b) != len(tape):
        return 0
    paths = []
    for i in range(len(a) + 1):
        row = []
        for j in range(len(b) + 1):
            row.append(0)
        paths.append(row)
    paths[0][0] = 1
    for i in range(len(a) + 1):
        for j in range(len(b) + 1):
            k = i + j - 1
            if i > 0 and a[i - 1] == tape[k]:
                paths[i][j] += paths[i - 1][j]
            if j > 0 and b[j - 1] == tape[k]:
                paths[i][j] += paths[i][j - 1]
    return paths[-1][-1]

